dtsPropsFor.TopBar:
title: React.ReactNode;
scope?: React.ReactNode;
period: string;
onPeriodChange: (value: string) => void;
/** null whenever the period is a named preset rather than a custom range. */
customRange: { from: string; to: string } | null;
onRangeSelect: (range: { from: string; to: string }) => void;
provider: string;
providerLabel: string;
providerOptions: { value: string; label: string }[];
onProviderSelect: (value: string) => void;
/** Omit to hide the fourth control entirely. */
claudeConfigs?: { selectedId: string | null; options: { id: string; label: string; path: string }[] };
/** null is the normal case — no explicit Claude config selected. */
configSource: string | null;
onConfigSelect: (id: string) => void;

dtsPropsFor.Sidebar:
active: 'overview' | 'sessions' | 'pullRequests' | 'spend' | 'optimize' | 'models' | 'compare' | 'plans' | 'settings' | 'plugins';
onNavigate: (section: 'overview' | 'sessions' | 'pullRequests' | 'spend' | 'optimize' | 'models' | 'compare' | 'plans' | 'settings' | 'plugins') => void;
/** Declared but NOT rendered by the current implementation. */
status?: React.ReactNode;

dtsPropsFor.SegTabs:
options: { value: string; label: string }[];
value: string;
onChange: (value: string) => void;
style?: React.CSSProperties;

dtsPropsFor.ProviderPop:
value: string;
/** Retained for API compatibility; the display label is derived from `options`. */
label: string;
options: { value: string; label: string }[];
onSelect: (value: string) => void;

dtsPropsFor.Dropdown:
value: string;
options: { value: string; label: string }[];
onChange: (value: string) => void;
ariaLabel: string;
id: string;
width?: React.CSSProperties['width'];
/** Optional leading glyph (e.g. a provider logo) shown in the trigger and each option. */
renderIcon?: (value: string) => React.ReactNode;
/** Optional non-interactive note pinned below the options in the open menu. */
footer?: React.ReactNode;

dtsPropsFor.RangeCalendar:
/** null when no custom range is selected. */
value: { from: string; to: string } | null;
onSelect: (range: { from: string; to: string }) => void;

dtsPropsFor.CliErrorPanel:
error: { kind: 'not-found' | 'nonzero' | 'bad-json' | 'timeout' | 'too-large' | 'bad-args'; message: string; cold?: true };
/** Named in the 'not-found' branch only, e.g. "sessions". */
subject?: string;

dtsPropsFor.ActivityHeatmap:
daily: { date: string; cost: number; savingsUSD: number; calls: number; inputTokens: number; outputTokens: number; cacheReadTokens: number; cacheWriteTokens: number; topModels: { name: string; cost: number; savingsUSD: number; calls: number; inputTokens: number; outputTokens: number }[] }[];
/** Drop the surrounding card chrome for embedding in a hero tile. */
bare?: boolean;

dtsPropsFor.StackedBars:
daily: { date: string; cost: number; savingsUSD: number; calls: number; inputTokens: number; outputTokens: number; cacheReadTokens: number; cacheWriteTokens: number; topModels: { name: string; cost: number; savingsUSD: number; calls: number; inputTokens: number; outputTokens: number }[] }[];
/** Label used when a provider filter leaves only cost data. */
fallbackLabel?: string;
/** Change to replay the entry animation. */
animateKey?: string;
/** ISO date of first recorded history; earlier bars render as a dashed no-data lead-in. */
dataStart?: string | null;

dtsPropsFor.TeamTabContent:
/** The CLI menubar payload (MenubarPayload in renderer/lib/types.ts) — a large
 *  aggregate; `current` plus the optional per-device and per-window sections. */
payload: { generated: string; stale?: boolean; current: { label: string } & Record<string, unknown> } & Record<string, unknown>;
/** Tab id from useTeamTabs(); an unknown id renders the fallback branch. */
tab: string;
